<?php

namespace Database\Factories;

use App\Enums\ExpenseStatus;
use App\Models\Expense;
use App\Models\ExpenseCategory;
use App\Models\User;
use Illuminate\Database\Eloquent\Factories\Factory;

class ExpenseFactory extends Factory
{
    protected $model = Expense::class;

    public function definition(): array
    {
        return [
            'expense_category_id' => ExpenseCategory::factory()->active(),
            // The expense number is generated by the creating model hook
            // (sequential, unique: EDAA-EXP-000001…).
            'amount' => fake()->randomFloat(2, 100, 10000),
            'currency' => 'BDT',
            'status' => ExpenseStatus::Recorded->value,
            'expense_date' => fake()->dateTimeBetween('-1 year', 'now')->format('Y-m-d'),
            'title' => fake()->sentence(4),
            'description' => fake()->optional(0.5)->paragraph(2),
            'reference' => fake()->optional(0.5)->numerify('Voucher ####'),
            'recorded_by' => User::factory()->admin(),
        ];
    }

    public function valid(): static
    {
        return $this->state(fn () => ['status' => ExpenseStatus::Recorded->value]);
    }

    public function recorded(): static
    {
        return $this->valid();
    }

    public function voided(): static
    {
        return $this->state(fn () => [
            'status' => ExpenseStatus::Void->value,
            'voided_at' => now(),
            'voided_by' => User::factory()->admin(),
            'void_reason' => 'Duplicate entry recorded during review.',
        ]);
    }

    public function forCategory(ExpenseCategory $category): static
    {
        return $this->state(fn () => ['expense_category_id' => $category->id]);
    }
}
